() => {
  // Find the Houzer 32" Double Bowl product link and return its URL
  const links = document.querySelectorAll('a');
  for (const link of links) {
    const ariaLabel = link.getAttribute('aria-label') || '';
    const title = link.title || '';
    const text = link.textContent || '';
    if (ariaLabel.includes('Houzer 32') || ariaLabel.includes('Double Bowl') || title.includes('Houzer 32') || text.includes('Houzer 32"')) {
      return {
        href: link.href,
        ariaLabel: ariaLabel,
        title: title,
        text: text.trim().substring(0, 100)
      };
    }
  }
  return null;
}

() => {
  // Find all product cards on the page
  const products = [];
  const allLinks = document.querySelectorAll('a.a-link-normal');
  for (const link of allLinks) {
    const text = link.textContent || '';
    const ariaLabel = link.getAttribute('aria-label') || '';
    const href = link.href || '';

    // Find product titles
    if ((ariaLabel && ariaLabel.includes('Stainless Steel') && ariaLabel.toLowerCase().includes('sink') && (ariaLabel.toLowerCase().includes('double bowl') || ariaLabel.toLowerCase().includes('60/40') || ariaLabel.toLowerCase().includes('50/50') || ariaLabel.toLowerCase().includes('80/20'))) ||
        (text.includes('Double Bowl') && text.toLowerCase().includes('stainless'))) {
      products.push({
        href: href,
        ariaLabel: ariaLabel.substring(0, 200),
        text: text.trim().substring(0, 100)
      });
    }
  }
  return products.slice(0, 20);
}

() => {
  // Find the Houzer 32 product by looking at all anchors
  const anchors = Array.from(document.querySelectorAll('a'));
  const results = [];
  for (const a of anchors) {
    const aria = a.getAttribute('aria-label') || '';
    const text = (a.textContent || '').trim();
    if (aria.includes('Houzer 32') || text.includes('Houzer 32')) {
      results.push({
        href: a.href,
        text: text.substring(0, 80),
        aria: aria.substring(0, 100)
      });
    }
  }
  return JSON.stringify(results.slice(0, 5));
}
